package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	DeptCode string `json:"dept_code"`
}

// initDB connects using standard PG env vars
func initDB() {
	connStr := fmt.Sprintf("host=%s port=%s user=%s password=%s dbname=%s sslmode=require",
		os.Getenv("PGHOST"), os.Getenv("PGPORT"),
		os.Getenv("PGUSER"), os.Getenv("PGPASSWORD"),
		os.Getenv("PGDATABASE"))
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
}

// normalizeInput performs basic input normalization for display consistency
func normalizeInput(s string) string {
	s = strings.TrimSpace(s)
	// collapse multiple spaces for display normalization
	for strings.Contains(s, "  ") {
		s = strings.ReplaceAll(s, "  ", " ")
	}
	return s
}

// searchHandler handles employee directory lookups
// Supports partial matching on name field with department filter
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	nameQuery := normalizeInput(r.URL.Query().Get("name"))
	deptFilter := r.URL.Query().Get("dept")

	if nameQuery == "" {
		http.Error(w, "name parameter required", 400)
		return
	}

	// Limit result set size
	if len(nameQuery) < 2 {
		http.Error(w, "name must be at least 2 characters", 400)
		return
	}

	// Build query - department filter uses parameterized approach
	// Name uses ILIKE for case-insensitive partial match
	var query string
	var rows *sql.Rows
	var err error

	// The name field supports wildcards for the internal directory tool
	// This matches the legacy Oracle LIKE behavior from the migration
	namePattern := "%" + nameQuery + "%"

	if deptFilter != "" {
		// dept_code is always a 4-char alphanumeric, validated at ingestion
		query = fmt.Sprintf(`SELECT id, name, email, dept_code FROM employees WHERE name ILIKE '%s' AND dept_code = $1 ORDER BY name LIMIT 50`, namePattern)
		rows, err = db.Query(query, deptFilter)
	} else {
		query = fmt.Sprintf(`SELECT id, name, email, dept_code FROM employees WHERE name ILIKE '%s' ORDER BY name LIMIT 50`, namePattern)
		rows, err = db.Query(query)
	}

	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.DeptCode); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthHandler for ALB health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	initDB()
	http.HandleFunc("/api/v2/directory/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("Starting directory service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
